"""Git hook installation and management utility."""

import os
import shutil
import stat
from pathlib import Path
from typing import Optional, Tuple

HOOK_HEADER = "# commit-msg-guard git hook"

HOOK_TEMPLATE = """#!/bin/sh
# commit-msg-guard git hook
# Auto-generated by commit-msg-guard

if command -v commit-msg-guard >/dev/null 2>&1; then
    exec commit-msg-guard check "$1"
elif command -v python3 >/dev/null 2>&1; then
    exec python3 -m commit_msg_guard check "$1"
elif command -v python >/dev/null 2>&1; then
    exec python -m commit_msg_guard check "$1"
else
    echo "[commit-msg-guard] Error: Neither commit-msg-guard nor python found in PATH." >&2
    exit 1
fi
"""


def find_git_dir(start_path: Optional[str] = None) -> Optional[Path]:
    """Locate the .git directory starting from start_path and walking upwards."""
    cur = Path(start_path or os.getcwd()).resolve()
    while True:
        candidate = cur / ".git"
        if candidate.is_dir():
            return candidate
        if candidate.is_file():
            # Submodule or git worktree
            try:
                content = candidate.read_text(encoding="utf-8").strip()
                if content.startswith("gitdir:"):
                    gitdir_path = (cur / content.split(":", 1)[1].strip()).resolve()
                    if gitdir_path.exists():
                        return gitdir_path
            except Exception:
                pass
        parent = cur.parent
        if parent == cur:
            break
        cur = parent
    return None


def install_hook(
    hook_type: str = "commit-msg",
    target_dir: Optional[str] = None,
    force: bool = False,
) -> Tuple[bool, str]:
    """Install git hook into repository .git/hooks directory."""
    if hook_type != "commit-msg":
        return False, f"Unsupported hook type: '{hook_type}'. Supported: 'commit-msg'"

    git_dir = find_git_dir(target_dir)
    if not git_dir:
        return False, "Not inside a git repository (could not find .git directory)."

    hooks_dir = git_dir / "hooks"
    hooks_dir.mkdir(parents=True, exist_ok=True)
    hook_file = hooks_dir / hook_type

    if hook_file.exists():
        content = ""
        try:
            content = hook_file.read_text(encoding="utf-8")
        except Exception:
            pass

        if HOOK_HEADER in content and not force:
            return True, f"Hook already installed at {hook_file}"

        if not force:
            backup_file = hook_file.with_name(f"{hook_type}.backup")
            shutil.copy2(hook_file, backup_file)
            backup_msg = f" (Existing hook backed up to {backup_file})"
        else:
            backup_msg = " (Forced overwrite)"
    else:
        backup_msg = ""

    # Write hook content
    hook_file.write_bytes(HOOK_TEMPLATE.encode("utf-8"))

    # Set executable permissions (chmod +x)
    try:
        current_stat = os.stat(hook_file)
        os.chmod(hook_file, current_stat.st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    except Exception:
        pass

    return True, f"Successfully installed '{hook_type}' hook to {hook_file}{backup_msg}"


def uninstall_hook(
    hook_type: str = "commit-msg",
    target_dir: Optional[str] = None,
) -> Tuple[bool, str]:
    """Uninstall git hook from repository .git/hooks directory."""
    if hook_type != "commit-msg":
        return False, f"Unsupported hook type: '{hook_type}'"

    git_dir = find_git_dir(target_dir)
    if not git_dir:
        return False, "Not inside a git repository."

    hook_file = git_dir / "hooks" / hook_type
    if not hook_file.exists():
        return False, f"Hook file does not exist at {hook_file}"

    # Check if this hook was created by commit-msg-guard
    try:
        content = hook_file.read_text(encoding="utf-8")
        if HOOK_HEADER not in content:
            return False, f"Hook file at {hook_file} was not generated by commit-msg-guard. Aborting removal."
    except Exception as e:
        return False, f"Failed to read hook file: {e}"

    hook_file.unlink()

    backup_file = hook_file.with_name(f"{hook_type}.backup")
    restored_msg = ""
    if backup_file.exists():
        shutil.move(str(backup_file), str(hook_file))
        restored_msg = f" Restored original hook from {backup_file}."

    return True, f"Successfully removed '{hook_type}' hook.{restored_msg}"
